$(".plug-parent__tab").click(function () {
    let parentBlock = $(this).parents(".plug-parent")
    let tabId = $(this).attr("data-tab")
    $(parentBlock).find(".plug-parent__tab").removeClass("_active")
    $(this).addClass("_active")
    $(parentBlock).find(".plug-card").removeClass("_active")
    $(parentBlock).addClass("_show-child")
    $(parentBlock).find(`.${tabId}`).addClass("_active")
})
